Definition LSR (m : mem) (ls : LS) (lo hi : Z) : Prop :=
  LSCells m ls /\ ls_sep ls /\ (forall a n, ls !! a = Some n -> a + 16 <= lo \/ hi <= a).

Lemma LSR_node : forall m ls lo hi a n, LSR m ls lo hi -> ls !! a = Some n ->
  lnode_wf n /\ (a + 16 <= lo \/ hi <= a) /\ rw_cells rsegs m a (LNodeCells n).
Proof.
  intros m ls lo hi a n (LC & SEP & OUT) L. split; [exact (LSCells_wf _ _ _ _ LC L)|]. split; [exact (OUT a n L)|].
  exact (LSCells_lookup _ _ _ _ LC L).
Qed.

Lemma LSR_store : forall m m' ls lo hi a n n' k w,
  LSR m ls lo hi -> ls !! a = Some n ->
  munch [(a + k, a + k + w)] m m' -> wmono rsegs m m' -> 0 <= k -> k + w <= 16 ->
  lnode_wf n' -> rw_cells rsegs m' a (LNodeCells n') ->
  LSR m' (<[ a := n' ]> ls) lo hi.
Proof.
  intros m m' ls lo hi a n n' k w (LC & SEP & OUT) L MU WM K1 K2 WF C.
  split; [eapply LSCells_update_node; eauto|].
  split.
  { intros x y nx ny Lx Ly NE.
    destruct (Z.eq_dec x a) as [->|NEx]; destruct (Z.eq_dec y a) as [->|NEy].
    - exfalso; exact (NE eq_refl).
    - rewrite lookup_insert_ne in Ly by (intros E; apply NEy; symmetry; exact E). exact (SEP a y n ny L Ly NE).
    - rewrite lookup_insert_ne in Lx by (intros E; apply NEx; symmetry; exact E). exact (SEP x a nx n Lx L NE).
    - rewrite lookup_insert_ne in Lx by (intros E; apply NEx; symmetry; exact E).
      rewrite lookup_insert_ne in Ly by (intros E; apply NEy; symmetry; exact E). exact (SEP x y nx ny Lx Ly NE). }
  intros x nx Lx. destruct (Z.eq_dec x a) as [->|NEx]; [exact (OUT a n L)|].
  rewrite lookup_insert_ne in Lx by (intros E; apply NEx; symmetry; exact E). exact (OUT x nx Lx).
Qed.

Lemma LSR_transport : forall W m m' ls lo hi,
  LSR m ls lo hi -> munch W m m' -> wmono rsegs m m' ->
  (forall a n, ls !! a = Some n -> disjoint_from W a 16) -> LSR m' ls lo hi.
Proof.
  intros W m m' ls lo hi (LC & SEP & OUT) MU WM D. split; [| split; [exact SEP| exact OUT]].
  eapply LSCells_transport; eauto.
Qed.

Lemma lb_load {R} (ls : LS) x off nd (K : Z -> option R) r :
  ls !! x = Some nd -> (lload ls x off ≫= K) = Some r -> K (lget_field off nd) = Some r.
Proof. intros L H. unfold lload in H. rewrite L in H. exact H. Qed.
Lemma lb_store {R} (ls : LS) x off v nd (K : LS -> option R) r :
  ls !! x = Some nd -> (lstore ls x off v ≫= K) = Some r -> K (<[x := lset_field off v nd]> ls) = Some r.
Proof. intros L H. unfold lstore in H. rewrite L in H. exact H. Qed.
Lemma l_store_last (ls : LS) x off v nd r : ls !! x = Some nd -> lstore ls x off v = Some r -> r = <[x := lset_field off v nd]> ls.
Proof. intros L H. unfold lstore in H. rewrite L in H. cbn in H. congruence. Qed.

(* [comment removed for export] *)
Ltac lnode LSRH L CH :=
  let WF := fresh "WF" in let B := fresh "B" in
  destruct (LSR_node _ _ _ _ _ _ LSRH L) as (WF & _ & CH);
  unfold lnode_wf in WF; unfold LNodeCells, wz in CH;
  pose proof (rw_cells_bound _ _ _ _ CH) as B; cbn [cells_size csize Nat.add] in B.

Ltac lmnode ls x nd L H :=
  destruct (ls !! x) as [nd|] eqn:L;
  [| exfalso; unfold get_next, get_prev, set_next, set_prev, lload, lstore in H;
     rewrite L in H; cbn [mbind option_bind] in H; discriminate].

Ltac lmstep H L :=
  first [ apply (lb_store _ _ _ _ _ _ _ L) in H | apply (lb_load _ _ _ _ _ _ L) in H
        | apply (l_store_last _ _ _ _ _ _ L) in H ];
  cbn [lget_field lset_field OFF_NEXT OFF_PREV Z.eqb Pos.eqb l_set_next l_set_prev l_next l_prev] in H.

Ltac lpost_store LSRk Lx ML WL CH n' k w :=
  let WFn := fresh "WFn" in
  assert (WFn : lnode_wf n') by (unfold lnode_wf; cbn [l_next l_prev l_set_next l_set_prev]; lia);
  let N := fresh "LSR" in
  pose proof (LSR_store _ _ _ _ _ _ _ n' k w LSRk Lx ML WL ltac:(lia) ltac:(lia) WFn CH) as N;
  clear LSRk ML WL CH WFn; rename N into LSRk.

Ltac lgen_store LSRk :=
  lazymatch type of LSRk with LSR _ ?lsk _ _ =>
    let lsv := fresh "ls" in let E := fresh "Els" in remember lsk as lsv eqn:E; clear E end.

(* [comment removed for export] *)
Ltac lload_step LSRk H x :=
  lazymatch type of LSRk with LSR _ ?ls _ _ =>
    let nd := fresh "ln" in let L := fresh "L" in let CH := fresh "CH" in
    lmnode ls x nd L H; lmstep H L; lnode LSRk L CH; step; clear CH;
    try match goal with B : 0 <= x /\ x + Z.of_nat 16 <= 2^64 |- _ => clear B end
  end.

(* [comment removed for export] *)
Ltac lstore_step LSRk H x k mk :=
  lazymatch type of LSRk with LSR _ ?ls _ _ =>
    let nd := fresh "ln" in let L := fresh "L" in let CH := fresh "CH" in let ML := fresh "ML" in let WL := fresh "WL" in
    lmnode ls x nd L H; lmstep H L; lnode LSRk L CH; pre_store CH k 8 ML WL; st1;
    let nd' := eval cbv beta in (mk nd) in
    lpost_store LSRk L ML WL CH nd' k 8; lgen_store LSRk; clear L;
    try match goal with B : 0 <= x /\ x + Z.of_nat 16 <= 2^64 |- _ => clear B end
  end.

