  Lemma ub_prefix_ext : forall k S, (forall x, x ∈ S -> key x = key' x) -> ub_prefix lt key k S = ub_prefix lt key' k S.
  Proof.
    induction S as [|a S IH]; intros AG; [reflexivity|]. cbn.
    rewrite <- (AG a) by (rewrite elem_of_cons; left; reflexivity).
    rewrite IH by (intros x Hx; apply AG; rewrite elem_of_cons; right; exact Hx). reflexivity.
  Qed.
  Lemma ub_suffix_ext : forall k S, (forall x, x ∈ S -> key x = key' x) -> ub_suffix lt key k S = ub_suffix lt key' k S.
  Proof.
    induction S as [|a S IH]; intros AG; [reflexivity|]. cbn.
    rewrite <- (AG a) by (rewrite elem_of_cons; left; reflexivity).
    rewrite IH by (intros x Hx; apply AG; rewrite elem_of_cons; right; exact Hx). reflexivity.
  Qed.
  Lemma has_eqv_ext : forall k S, (forall x, x ∈ S -> key x = key' x) -> (has_eqv lt key k S <-> has_eqv lt key' k S).
  Proof.
    intros k S AG. unfold has_eqv. split; intros (x & Hx & E); exists x; split; [exact Hx| | exact Hx|].
    - rewrite <- (AG x Hx). exact E.
    - rewrite (AG x Hx). exact E.
  Qed.
