Definition new_elt_ok (em : gmap Z elt) (e : Z) (d : elt) : Prop :=
  0 < e /\ e mod 8 = 0 /\ e + esize d <= hceil /\ elt_wf d
  /\ (forall e' d', em !! e' = Some d' -> e + esize d <= e' \/ e' + esize d' <= e).
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.option Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Specif.sumbool Sort Prop.

