(* [comment removed for export] *)
Lemma FieldsC_assemble : forall m Fa S L ns ls em e d S' L' ns' ls',
  FieldsC m Fa S L ns ls em -> new_elt_ok em e d ->
  (forall m1, NSCells m1 ns' -> LSCells m1 ls' -> EMCells m1 (<[e := d]> em) ->
   rb_ok Fa S' ns' -> sorted key_lt (key_of (<[e := d]> em)) S' -> dl_ok (Fa + 32) L' ls' ->
   (forall x, x ∈ S' -> x - 16 ∈ L') -> (forall a, a ∈ L' <-> a = e \/ a ∈ L) ->
   FieldsC m1 Fa S' L' ns' ls' (<[e := d]> em)).
Proof.
  intros m Fa S L ns ls em e d S' L' ns' ls' FC NEW m1 NC LC EC OK SO DL SL LEQ.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LE & EOK & HH & HB & ALF).
  destruct (new_elt_fresh _ _ _ _ _ _ _ _ _ FC NEW) as (NONE & _ & _ & _ & _ & _ & _ & _ & EOK').
  split; [exact NC|]. split; [exact LC|]. split; [exact EC|]. split; [exact OK|]. split; [exact SO|]. split; [exact DL|].
  split; [exact SL|]. split.
  { intros a. rewrite LEQ. destruct (Z.eq_dec a e) as [->|NE].
    - rewrite lookup_insert_eq. split; [intros _; eexists; reflexivity| intros _; left; reflexivity].
    - rewrite lookup_insert_ne by (intros E; apply NE; symmetry; exact E). rewrite <- LE.
      split; [intros [E|IN]; [exfalso; exact (NE E)| exact IN]| intros IN; right; exact IN]. }
  split; [exact EOK'|]. split; [exact HH|]. split; [exact HB| exact ALF].
Qed.


(* [comment removed for export] *)
Lemma LNodeCells_of_junk : forall m a junk,
  rw_cells rsegs m a [CB 16 junk] -> exists ln, lnode_wf ln /\ rw_cells rsegs m a (LNodeCells ln).
Proof.
  intros m a junk H.
  pose proof H as [[WF _] _]. cbn in WF. destruct WF as [L _].
  set (b0 := firstn 8 junk). set (b1 := skipn 8 junk).
  assert (L0 : length b0 = 8%nat) by (subst b0; rewrite length_firstn; lia).
  assert (L1 : length b1 = 8%nat) by (subst b1; rewrite length_skipn; lia).
  assert (EJ : junk = b0 ++ b1) by (subst b0 b1; symmetry; apply firstn_skipn).
  pose proof (bytes_le_to_Z_bound b0) as B0. rewrite L0 in B0. pose proof (bytes_le_to_Z_bound b1) as B1. rewrite L1 in B1.
  cbn in B0, B1.
  exists (mkLNode (bytes_le_to_Z b0) (bytes_le_to_Z b1)).
