  rw_cells rsegs m e [CB 48 junk] -> rw_cells rsegs m (e + 48) (ValCells d) -> new_elt_ok em e d ->
  stk rsegs m lo (bv_unsigned sp) -> lo + INSEL_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= Fa ->
  mem_inv rsegs m ->
  evt rsegs (insel_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa e d L em lo m)
