Lemma FieldsC_LSR_new : forall m Fa S L ns ls em e d j16 lo (sp : word),
  FieldsC m Fa S L ns ls em -> new_elt_ok em e d ->
  rw_cells rsegs m e [CB 16 j16] -> hceil <= lo -> bv_unsigned sp <= Fa ->
  exists ln0, lnode_wf ln0 /\ rw_cells rsegs m e (LNodeCells ln0) /\ LSR m (<[e := ln0]> ls) lo (bv_unsigned sp)
    /\ (forall a n, (<[e := ln0]> ls) !! a = Some n -> a = e \/ ls !! a = Some n).
Proof.
  intros m Fa S L ns ls em e d j16 lo sp FC NEW RAW HL SPF.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & HHF & HB & AL).
  pose proof NEW as (EP & EAL & EHI & WFd & DJ). pose proof (esize_ge d) as EG.
  destruct (LNodeCells_of_junk _ _ _ RAW) as (ln0 & WF & CH).
  assert (CASE : forall c n, (<[e := ln0]> ls) !! c = Some n -> c = e \/ ls !! c = Some n).
