  (* [comment removed for export] *)
  Lemma ie_finish : forall m2 mx ns' lsF L' p1 p2 n1 n2 j8 (w8 w16 : word)
      (x1 x5 x6 x7 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x x28 x29 x30 x31 : word),
    NSR m2 ns' lo (bv_unsigned sp + -80) X -> rb_ok Fa (ubA ++ (e + 16) :: ubB) ns' -> EMCells m2 em ->
    ls !! p1 = Some n1 -> ls !! p2 = Some n2 ->
    LSR mx lsF lo (bv_unsigned sp) -> dl_ok (Fa + 32) L' lsF -> (forall a, a ∈ L' <-> a = e \/ a ∈ L) -> e ∈ L' ->
    munch [(e, e + 16); (p1, p1 + 16); (p2, p2 + 16)]%Z m2 mx -> wmono rsegs m2 mx -> mem_inv rsegs mx ->
    munch (insW lo (bv_unsigned sp) Fa (e :: L)) m mx -> wmono rsegs m mx -> stk rsegs mx lo (bv_unsigned sp + -80) ->
    rw_cells rsegs mx (bv_unsigned sp + -80) [CB 8 j8] -> rw_cells rsegs mx (bv_unsigned sp + -72) [C8 w8; C8 w16] ->
    rw_cells rsegs mx (bv_unsigned sp + -56) [C8 (Z_to_bv 64 Fa); C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells rsegs mx (e + 48) (ValCells d) -> bytes_at rsegs mx (e + 56) name ->
    evt rsegs (insel_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa e d L em lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp x5 x6 x7 (Z_to_bv 64 e) (Z_to_bv 64 Fa)
                a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
